/// ICU `localeCompare` between two corpus strings: `None` when either is unknown.
pub fn locale_cmp(a: &str, b: &str) -> Option<std::cmp::Ordering> {
    let ga = RANKED.split('\u{1}').zip(GROUPS).find(|(s, _)| *s == a)?;
    let gb = RANKED.split('\u{1}').zip(GROUPS).find(|(s, _)| *s == b)?;
    Some(ga.1.cmp(gb.1))
}
